tion_method=?,notes=?,updated_by=?,updated_by_name=? WHERE id=?')->execute([$courier,$number,$date,$currency,tc_money($subtotal),tc_money($vat),tc_money($basis==='including'?$amount:$amount+$vat),tc_money($other),$vatTreatment,tc_money($allocable),$weightStatus==='actual'?$weight:null,$weightStatus==='estimated'?$weight:null,(string)($b['weight_source']??'Unknown'),$method,trim((string)($b['notes']??'')),$u['id'],$u['name'],$id]);}else{$pdo->prepare("INSERT INTO cw_transport_records(entry_source,courier_name,invoice_number,transport_date,currency,subtotal_ex_vat,vat_amount,total_inc_vat,non_transport_charges,vat_treatment,allocable_amount,actual_weight_kg,estimated_weight_kg,weight_source,allocation_method,notes,extraction_status,created_by,created_by_name) VALUES('manual',?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,'manual_review',?,?)")->execute([$courier,$number,$date,$currency,tc_money($subtotal),tc_money($vat),tc_money($basis==='including'?$amount:$amount+$vat),tc_money($other),$vatTreatment,tc_money($allocable),$weightStatus==='actual'?$weight:null,$weightStatus==='estimated'?$weight:null,(string)($b['weight_source']??'Manual estimate'),$method,trim((string)($b['notes']??'')),$u['id'],$u['name']]);$id=(int)$pdo->lastInsertId();}$allocs=[];$sum=0;$totalWeight=array_sum(array_map(fn($x)=>tc_num($x['weight_kg']??0),$links));$count=count($links);foreach($links as $index=>$link){$w=tc_num($link['weight_kg']??0);$value=tc_num($link['value']??0);if($method==='by_weight')$calc=$totalWeight>0?$allocable*$w/$totalWeight:0;elseif($method==='percentage')$calc=$allocable*$value/100;elseif($method==='equal_split')$calc=$count?$allocable/$count:0;else$calc=$value;$calc=round($calc,2);if($index===$count-1&&$method!=='manual_amount'&&$method!=='courier_lines')$calc=round($allocable-$sum,2);$sum+=$calc;$allocs[]=['supplier_invoice_id'=>(int)$link['supplier_invoice_id'],'weight'=>$w,'value'=>$value,'amount'=>$calc,'weight_status'=>$w>0?((string)($link['weight_status']??'estimated')):'missing'];}if($sum>$allocable+.005)throw new RuntimeException('Allocated amounts cannot exceed the transport amount available for allocation.');if($method==='percentage'&&$count&&abs(array_sum(array_map(fn($x)=>tc_num($x['value']??0),$links))-100)>.001)throw new RuntimeException('Allocation percentages must total 100%.');$pdo->prepare('DELETE FROM cw_transport_allocations WHERE transport_id=?')->execute([$id]);$ins=$pdo->prepare('INSERT INTO cw_transport_allocations(transport_id,supplier_invoice_id,allocation_method,weight_kg_snapshot,weight_status,allocation_percentage,calculated_amount,calculation_date) VALUES(?,?,?,?,?,?,?,NOW())');foreach($allocs as $a){$ins->execute([$id,$a['supplier_invoice_id'],$method,$a['weight']?:null,$a['weight_status'],$method==='percentage'?$a['value']:null,tc_money($a['amount'])]);$aid=(int)$pdo->lastInsertId();$lines=$pdo->prepare('SELECT id,quantity,pack_size,base_quantity,base_unit FROM cw_supplier_invoice_lines WHERE supplier_invoice_id=?');$lines->execute([$a['supplier_invoice_id']]);$productRows=$lines->fetchAll();$weights=[];$weightSum=0;foreach($productRows as $line){$shipping=(string)$line['base_unit']==='kg'?(float)$line['base_quantity']:0;$weights[(int)$line['id']]=$shipping;$weightSum+=$shipping;}if($weightSum>0){$pi=$pdo->prepare('INSERT INTO cw_transport_product_allocations(transport_allocation_id,supplier_invoice_line_id,quantity_snapshot,pack_size_snapshot,base_quantity_snapshot,base_unit_snapshot,shipping_weight_kg_snapshot,calculated_amount,transport_cost_per_base) VALUES(?,?,?,?,?,?,?,?,?)');$ps=0;foreach($productRows as $ix=>$line){$share=$a['amount']*$weights[(int)$line['id']]/$weightSum;$share=$ix===count($productRows)-1?$a['amount']-$ps:round($share,2);$ps+=$share;$base=(float)$line['base_quantity'];$pi->execute([$aid,$line['id'],$line['quantity'],$line['pack_size'],$line['base_quantity'],$line['base_unit'],$weights[(int)$line['id']],tc_money($share),$base>0?number_format($share/$base,6,'.',''):null]);}}}$remaining=max(0,$allocable-$sum);$status=$count===0?'unlinked':($remaining<.005?'fully_allocated':'partial');if($method==='by_weight'&&$count&&$totalWeight<=0)$status='missing_weight';$pdo->prepare('UPDATE cw_transport_records SET allocation_status=? WHERE id=?')->execute([$status,$id]);$pdo->prepare('INSERT INTO cw_transport_audit(transport_id,action_key,after_json,actor_id,actor_name) VALUES(?,?,?,?,?)')->execute([$id,'allocation_saved',json_encode(['method'=>$method,'allocated'=>$sum,'remaining'=>$remaining]),$u['id'],$u['name']]);$pdo->commit();tc_reply(['ok'=>true,'id'=>$id,'allocated'=>tc_money($sum),'unallocated'=>tc_money($remaining),'status'=>$status,'message'=>'Transport allocation saved.']);}
